def P(text, style="Bodyx"):
    return Paragraph(text, styles[style])

def link(label, url):
    return f'<link href="{url}" color="#1B5E7A"><u>{label}</u></link>'

def bullet_list(items):
    return ListFlowable([ListItem(P(x, "Bodyx")) for x in items], bulletType="bullet", leftIndent=7*mm, bulletFontName="Arial", bulletFontSize=7, bulletOffsetY=2, spaceAfter=1.5*mm)

def source_line(text):
    return P("<b>Источники блока.</b> " + text, "Smallx")

def info_table(rows, widths, small=False):
    data = []
    for ri, row in enumerate(rows):
        cells = []
        for cell in row:
            if isinstance(cell, Paragraph):
                cells.append(cell)
            else:
                cells.append(P(str(cell), "TableHead" if ri == 0 else "TableCell"))
        data.append(cells)
    t = Table(data, colWidths=widths, repeatRows=1, hAlign="LEFT")
    cmds = [("GRID",(0,0),(-1,-1),0.35,GRID),("VALIGN",(0,0),(-1,-1),"TOP"),
            ("LEFTPADDING",(0,0),(-1,-1),4),("RIGHTPADDING",(0,0),(-1,-1),4),
            ("TOPPADDING",(0,0),(-1,-1),4),("BOTTOMPADDING",(0,0),(-1,-1),4),
            ("BACKGROUND",(0,0),(-1,0),NAVY),("TEXTCOLOR",(0,0),(-1,0),WHITE)]
    for i in range(2, len(rows), 2):
        cmds.append(("BACKGROUND",(0,i),(-1,i),PALE))
    t.setStyle(TableStyle(cmds))
    return t

def metric_card(code, title, formula, meaning, color):
    t = Table([[P(f"<font color='{color.hexval()}'><b>{code}</b></font>", "H2x")],
               [P(f"<b>{title}</b><br/>{formula}", "Bodyx")],
               [P(meaning, "Smallx")]], colWidths=[55*mm], hAlign="LEFT")
    t.setStyle(TableStyle([("BOX",(0,0),(-1,-1),0.6,color),("BACKGROUND",(0,0),(-1,-1),PALE),
                           ("LEFTPADDING",(0,0),(-1,-1),6),("RIGHTPADDING",(0,0),(-1,-1),6),
                           ("TOPPADDING",(0,0),(-1,-1),5),("BOTTOMPADDING",(0,0),(-1,-1),5)]))
    return t

class NumberedCanvas(Canvas):
    def __init__(self, *args, **kwargs):
        Canvas.__init__(self, *args, **kwargs)
        self._saved_page_states = []
    def showPage(self):
        self._saved_page_states.append(dict(self.__dict__))
        self._startPage()
    def save(self):
        total = len(self._saved_page_states)
        for state in self._saved_page_states:
            self.__dict__.update(state)
            if self._pageNumber != 1:
                self.saveState()
                self.setStrokeColor(GRID)
                self.setLineWidth(0.4)
                self.line(18*mm, 13*mm, 192*mm, 13*mm)
                self.setFont("Arial", 7.5)
                self.setFillColor(MUTED)
                self.drawString(18*mm, 8.5*mm, "Экологические последствия работы ЦОД")
                self.drawRightString(192*mm, 8.5*mm, f"{self._pageNumber} / {total}")
                self.restoreState()
            Canvas.showPage(self)
        Canvas.save(self)

