def on_page(canvas, doc):
    if doc.page == 1:
        canvas.saveState()
        canvas.setFillColor(NAVY)
        canvas.rect(0,0,A4[0],A4[1],fill=1,stroke=0)
        canvas.restoreState()
    elif doc.page == 2:
        canvas.saveState()
        canvas.setFillColor(INK)
        canvas.setFont("Arial",7.5)
        canvas.drawString(18*mm,A4[1]-12*mm,"Содержание и основные выводы")
        canvas.restoreState()

def main():
    doc = SimpleDocTemplate(OUT, pagesize=A4, rightMargin=18*mm, leftMargin=18*mm, topMargin=18*mm, bottomMargin=17*mm, title="Экологические последствия работы центров обработки данных", author="OpenAI Codex")
    doc.build(build_story_v3(), onFirstPage=on_page, onLaterPages=on_page, canvasmaker=NumberedCanvas)
    print(OUT)

if __name__ == "__main__":
    main()
